require "test_helper"

class ModerationAuthAndHttpTest < ActionDispatch::IntegrationTest
  setup do
    @quiz = Quiz.create!(title: "Auth Test Quiz")
    @question = @quiz.questions.new
    @question.save_with_option_rows(
      { body: "Is HTTP stateless?", active: true },
      {
        "0" => { text: "Yes", correct: "1" },
        "1" => { text: "No", correct: "0" }
      }
    )
  end

  test "GET /up responds 200 without auth on arbitrary host" do
    host! "custom-projector-wall.conference.local"
    get "/up"
    assert_response :success
  end

  test "all /moderate endpoints return 401 for missing or wrong credentials" do
    endpoints = [
      [ :get, "/moderate" ],
      [ :get, "/moderate/quizzes/new" ],
      [ :post, "/moderate/quizzes" ],
      [ :get, "/moderate/quizzes/#{@quiz.id}" ],
      [ :get, "/moderate/quizzes/#{@quiz.id}/settings" ],
      [ :patch, "/moderate/quizzes/#{@quiz.id}" ],
      [ :delete, "/moderate/quizzes/#{@quiz.id}" ],
      [ :get, "/moderate/quizzes/#{@quiz.id}/preview" ],
      [ :get, "/moderate/quizzes/#{@quiz.id}/questions/new" ],
      [ :post, "/moderate/quizzes/#{@quiz.id}/questions" ],
      [ :get, "/moderate/quizzes/#{@quiz.id}/questions/#{@question.id}/edit" ],
      [ :patch, "/moderate/quizzes/#{@quiz.id}/questions/#{@question.id}" ],
      [ :delete, "/moderate/quizzes/#{@quiz.id}/questions/#{@question.id}" ],
      [ :patch, "/moderate/quizzes/#{@quiz.id}/questions/#{@question.id}/move_up" ],
      [ :patch, "/moderate/quizzes/#{@quiz.id}/questions/#{@question.id}/move_down" ],
      [ :patch, "/moderate/quizzes/#{@quiz.id}/questions/#{@question.id}/toggle_active" ],
      [ :get, "/moderate/unknown-subpath" ]
    ]

    endpoints.each do |method, path|
      send(method, path)
      assert_response :unauthorized, "Expected 401 without credentials for #{method.upcase} #{path}"

      send(method, path, headers: moderator_auth_headers("wrong", ENV["QUIZZY_MODERATOR_PASSWORD"]))
      assert_response :unauthorized, "Expected 401 with wrong username for #{method.upcase} #{path}"

      send(method, path, headers: moderator_auth_headers(ENV["QUIZZY_MODERATOR_USERNAME"], "wrong"))
      assert_response :unauthorized, "Expected 401 with wrong password for #{method.upcase} #{path}"
    end

    get "/moderate", headers: moderator_auth_headers
    assert_response :success
  end
end

