import "@hotwired/turbo-rails"
import "controllers"
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  submit(event) {
    const checkbox = event.currentTarget
    const form = this.element
    const item = form.closest(".question-item")

    if (item) {
      item.classList.toggle("question-item--inactive", !checkbox.checked)
    }

    const allItems = document.querySelectorAll(".question-list .question-item")
    let activeCount = 0

    allItems.forEach((qItem) => {
      const cb = qItem.querySelector("input[type='checkbox']")
      const numEl = qItem.querySelector(".question-item__num")
      if (cb && cb.checked) {
        activeCount += 1
        if (numEl) numEl.textContent = String(activeCount)
      } else {
        if (numEl) numEl.textContent = "—"
      }
    })

    const summaryEl = document.getElementById("quiz-active-summary")
    if (summaryEl) {
      const total = allItems.length
      const word = total === 1 ? "question" : "questions"
      summaryEl.textContent = `${activeCount} of ${total} ${word} active`
    }

    const csrfToken = document.querySelector("meta[name='csrf-token']")?.content || ""
    const actionPath = form.getAttribute("action")

    fetch(actionPath, {
      method: "POST",
      body: new FormData(form),
      keepalive: true,
      credentials: "same-origin",
      headers: {
        "X-CSRF-Token": csrfToken,
        "X-Quizzy-Async": "1"
      }
    })
  }
}
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["list", "row"]

  connect() {
    this.nextKey = this.rowTargets.length
  }

  add() {
    const key = this.nextKey++
    const num = this.rowTargets.length + 1

    const row = document.createElement("div")
    row.className = "option-row"
    row.dataset.optionRowsTarget = "row"

    const textWrap = document.createElement("div")
    const textLabel = document.createElement("label")
    textLabel.className = "visually-hidden"
    textLabel.dataset.role = "text-label"
    textLabel.htmlFor = `question_option_${key}_text`
    textLabel.textContent = `Option ${num}`

    const textInput = document.createElement("input")
    textInput.id = `question_option_${key}_text`
    textInput.className = "input"
    textInput.type = "text"
    textInput.name = `question[option_rows][${key}][text]`
    textInput.placeholder = `Option ${num}`
    textInput.setAttribute("aria-label", `Option ${num}`)
    textInput.dataset.role = "text-input"

    textWrap.append(textLabel, textInput)

    const correctWrap = document.createElement("div")
    const hiddenCorrect = document.createElement("input")
    hiddenCorrect.type = "hidden"
    hiddenCorrect.name = `question[option_rows][${key}][correct]`
    hiddenCorrect.value = "0"

    const visibleLabel = document.createElement("label")
    visibleLabel.className = "checkbox"
    visibleLabel.htmlFor = `question_option_${key}_correct`

    const checkbox = document.createElement("input")
    checkbox.id = `question_option_${key}_correct`
    checkbox.type = "checkbox"
    checkbox.name = `question[option_rows][${key}][correct]`
    checkbox.value = "1"
    checkbox.setAttribute("aria-label", `Option ${num} is correct`)
    checkbox.dataset.role = "correct-input"

    visibleLabel.append(checkbox, document.createTextNode(" Correct"))

    const hiddenLabel = document.createElement("label")
    hiddenLabel.className = "visually-hidden"
    hiddenLabel.dataset.role = "correct-label"
    hiddenLabel.htmlFor = `question_option_${key}_correct`
    hiddenLabel.textContent = `Option ${num} is correct`

    correctWrap.append(hiddenCorrect, visibleLabel, hiddenLabel)

    const removeBtn = document.createElement("button")
    removeBtn.type = "button"
    removeBtn.className = "btn btn--danger btn--icon"
    removeBtn.dataset.action = "click->option-rows#remove"
    removeBtn.dataset.role = "remove-btn"
    removeBtn.setAttribute("aria-label", `Remove option ${num}`)
    removeBtn.title = `Remove option ${num}`
    removeBtn.textContent = "✕"

    row.append(textWrap, correctWrap, removeBtn)
    this.listTarget.appendChild(row)
    textInput.focus()
  }

  remove(event) {
    const row = event.currentTarget.closest("[data-option-rows-target='row']")
    if (row) {
      row.remove()
      this.renumber()
    }
  }

  renumber() {
    this.rowTargets.forEach((row, index) => {
      const num = index + 1
      const textLabel = row.querySelector("[data-role='text-label']")
      const textInput = row.querySelector("[data-role='text-input']")
      const correctInput = row.querySelector("[data-role='correct-input']")
      const correctLabel = row.querySelector("[data-role='correct-label']")
      const removeBtn = row.querySelector("[data-role='remove-btn']")

      if (textLabel) textLabel.textContent = `Option ${num}`
      if (textInput) {
        textInput.placeholder = `Option ${num}`
        textInput.setAttribute("aria-label", `Option ${num}`)
      }
      if (correctInput) {
        correctInput.setAttribute("aria-label", `Option ${num} is correct`)
      }
      if (correctLabel) correctLabel.textContent = `Option ${num} is correct`
      if (removeBtn) {
        removeBtn.setAttribute("aria-label", `Remove option ${num}`)
        removeBtn.title = `Remove option ${num}`
      }
    })
  }
}
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static values = { questions: Array }
  static targets = [
    "questionView",
    "scoreView",
    "progress",
    "body",
    "options",
    "feedback",
    "actions",
    "scoreText"
  ]

  connect() {
    this.currentIndex = 0
    this.score = 0
    this.answered = false
    if (this.questionsValue.length > 0) {
      this.renderQuestion()
    }
  }

  optionLetter(index) {
    let n = index
    let result = ""
    while (n >= 0) {
      result = String.fromCharCode(65 + (n % 26)) + result
      n = Math.floor(n / 26) - 1
    }
    return result
  }

  renderQuestion() {
    const total = this.questionsValue.length
    const question = this.questionsValue[this.currentIndex]
    this.answered = false

    this.scoreViewTarget.hidden = true
    this.questionViewTarget.hidden = false

    this.progressTarget.textContent = `Question ${this.currentIndex + 1} of ${total}`
    this.bodyTarget.textContent = question.body

    this.optionsTarget.className = "play-options"
    this.optionsTarget.replaceChildren()

    question.options.forEach((opt, idx) => {
      const btn = document.createElement("button")
      btn.type = "button"
      btn.className = "play-option"
      btn.title = opt.text
      btn.setAttribute("aria-label", opt.text)
      btn.dataset.index = String(idx)
      btn.dataset.action = "click->preview#pick"

      const letter = document.createElement("span")
      letter.className = "play-option__letter"
      letter.textContent = this.optionLetter(idx)

      const title = document.createElement("span")
      title.className = "play-option__title"
      title.textContent = opt.text

      btn.append(letter, title)
      this.optionsTarget.appendChild(btn)
    })

    this.feedbackTarget.hidden = true
    this.feedbackTarget.textContent = ""

    this.actionsTarget.hidden = true
    this.actionsTarget.replaceChildren()
  }

  pick(event) {
    if (this.answered) return
    this.answered = true

    const pickedIndex = Number(event.currentTarget.dataset.index)
    const question = this.questionsValue[this.currentIndex]
    const pickedOption = question.options[pickedIndex]
    const isCorrect = Boolean(pickedOption?.correct)

    if (isCorrect) {
      this.score += 1
    }

    this.optionsTarget.classList.add("is-locked", "is-revealed")
    const buttons = this.optionsTarget.querySelectorAll(".play-option")

    buttons.forEach((btn, idx) => {
      if (idx === pickedIndex) {
        btn.classList.add("is-picked")
      }
      if (question.options[idx]?.correct) {
        btn.classList.add("is-correct")
        btn.dataset.correct = "true"
        const mark = document.createElement("span")
        mark.className = "play-option__mark"
        mark.textContent = "✓"
        btn.appendChild(mark)
      }
    })

    this.feedbackTarget.hidden = false
    this.feedbackTarget.className = isCorrect
      ? "play-status play-status--right"
      : "play-status play-status--wrong"
    this.feedbackTarget.textContent = isCorrect ? "Correct!" : "Wrong!"

    this.actionsTarget.hidden = false
    this.actionsTarget.replaceChildren()

    const nextBtn = document.createElement("button")
    nextBtn.type = "button"
    nextBtn.className = "btn btn--pink"

    if (this.currentIndex < this.questionsValue.length - 1) {
      nextBtn.textContent = "Next question"
      nextBtn.dataset.action = "click->preview#next"
    } else {
      nextBtn.textContent = "See score"
      nextBtn.dataset.action = "click->preview#seeScore"
    }

    this.actionsTarget.appendChild(nextBtn)
  }

  next() {
    if (this.currentIndex < this.questionsValue.length - 1) {
      this.currentIndex += 1
      this.renderQuestion()
    }
  }

  seeScore() {
    this.questionViewTarget.hidden = true
    this.scoreViewTarget.hidden = false
    this.scoreTextTarget.textContent = `Score: ${this.score}/${this.questionsValue.length}`
  }

  restart() {
    this.currentIndex = 0
    this.score = 0
    this.answered = false
    this.renderQuestion()
  }
}
